#!/usr/bin/env node
/**
 * parse-elamigos.mjs — Fetch & parse the ElAmigos repack catalog (elamigos.site)
 *
 * Produces:
 *   public/data/elamigos-games.json  (full records, used by the importer)
 *   public/data/elamigos-index.json  (lightweight listing, regenerated by make-indexes)
 *
 * Modes:
 *   node scripts/parse-elamigos.mjs                 # live: fetch index + ALL detail pages
 *   node scripts/parse-elamigos.mjs --limit 50      # live: only the 50 most recent games
 *   node scripts/parse-elamigos.mjs --raw <dir>     # offline: read index.md/detail*.md from <dir>
 *
 * Offline mode is used in sandboxes without outbound network: save the site's
 * pages as markdown (or HTML) under <dir>/index.md and <dir>/<slug>.md.
 *
 * ElAmigos pages contain only link-protector pages (filecrypt.cc / keeplinks.org),
 * one per mirror section (DDOWNLOAD, RAPIDGATOR, TORRENT, ...). Per the
 * "captcha hoster → use the link before the captcha" rule, those protector URLs
 * are stored as the download entries, named after the mirror hoster.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const OUT_FULL = join(ROOT, "public", "data", "elamigos-games.json");

const BASE = "https://elamigos.site";
const INDEX_URL = BASE + "/";
const CONC = 12;
const DETAIL_TIMEOUT_MS = 20000;

const args = process.argv.slice(2);
const limitArg = args.indexOf("--limit");
const LIMIT = limitArg >= 0 ? parseInt(args[limitArg + 1], 10) : 0;
const rawArg = args.indexOf("--raw");
const RAW_DIR = rawArg >= 0 ? args[rawArg + 1] : "";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* ------------------------------------------------------------------ */
/* HTML -> markdown-ish canonical text (fetch_page already gives us    */
/* markdown, but live fetches get raw HTML; this covers both).         */
/* ------------------------------------------------------------------ */
function toCanonical(input) {
  if (input == null) return "";
  let t = String(input);
  const looksHtml = /<\/?[a-z][\s\S]*>/i.test(t);
  if (!looksHtml) return t.replace(/\r\n/g, "\n");
  t = t
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<meta[^>]*>/gi, "")
    .replace(/<link[^>]*>/gi, "")
    // headings
    .replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, "\n# $1\n")
    .replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, "\n## $1\n")
    .replace(/<h[3-6][^>]*>([\s\S]*?)<\/h[3-6]>/gi, "\n### $1\n")
    // anchors -> [text](href); links shown as raw URLs (ElAmigos style) stay as-is
    .replace(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (m, href, inner) => {
      const text = inner.replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim();
      if (!href) return text;
      // Anchor whose visible text is the URL itself -> keep the raw URL.
      if (!text || text.replace(/\/$/, "") === href.replace(/\/$/, "")) return ` ${href} `;
      return `[${text}](${href})`;
    })
    .replace(/<img\b[^>]*src=["']([^"']+)["'][^>]*>/gi, "\n![]($1)\n")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(?:p|div|tr|li|table)>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;|&#0?160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");
  return t.replace(/\r\n/g, "\n");
}

/* ------------------------------------------------------------------ */
/* Index page: title + detail URL for every release                    */
/* ------------------------------------------------------------------ */
function parseIndex(md) {
  const out = [];
  const seen = new Set();
  let date = "";
  // Headings:  # 29.08.2026   /   ### Title ... [DOWNLOAD](.../data/<slug>.html)
  const lines = md.split("\n");
  for (const line of lines) {
    const dm = line.match(/^#{1,6}\s*(\d{2}\.\d{2}\.\d{4})\s*$/);
    if (dm) {
      date = dm[1];
      continue;
    }
    const hm = line.match(/^#{2,6}\s+([\s\S]+)$/);
    if (!hm) continue;
    const inner = hm[1];
    const lm = inner.match(/\]\((https?:\/\/elamigos\.site\/data\/([^)]+\.html))\)/);
    if (!lm) continue;
    const url = lm[1];
    const slug = lm[2];
    if (seen.has(slug)) continue;
    seen.add(slug);
    // Title = heading text before the [DOWNLOAD] link, minus ElAmigos/updates noise.
    let title = inner
      .replace(/\[DOWNLOAD\]\([^)]+\)/gi, "")
      .replace(/\\?\[(?:Update|Build|CrackFix)[^\]]*\]/gi, "")
      // "+[Update x]" markers (sometimes split across the heading) -> "+"
      .replace(/\\?\+\s*(?:\[(?:Update|Build|CrackFix)[^\]]*\])?/gi, " ")
      .replace(/<[^>]+>/g, "")
      .replace(/\s+/g, " ")
      .trim();
    // Drop trailing "ElAmigos" marker word(s) and any dangling "+".
    title = title.replace(/\s+ElAmigos\s*$/i, "").replace(/\s*\+\s*$/g, "").trim();
    out.push({ title, url, slug, date });
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Mirror link hosters used by ElAmigos                                */
/* ------------------------------------------------------------------ */
const MIRROR_HOSTS = {
  DDOWNLOAD: "DDownload",
  DDL: "DDownload",
  RAPIDGATOR: "RapidGator",
  RG: "RapidGator",
  TORRENT: "Torrent",
  MEGA: "MEGA",
  MEDIAFIRE: "MediaFire",
  KATFILE: "KatFile",
  UPTOBOX: "Uptobox",
  NITROFLARE: "NitroFlare",
  "1FICHIER": "1Fichier",
  GOFILE: "GoFile",
  PIXELDRAIN: "PixelDrain",
  BAYFILES: "BayFiles",
};

function linkHostLabel(u) {
  try {
    const host = new URL(u).hostname.replace(/^www\./, "");
    if (/filecrypt/.test(host)) return "FileCrypt";
    if (/keeplinks/.test(host)) return "KeepLinks";
    if (/^magnet:/.test(u) || /\.torrent(\?|$)/i.test(u)) return "Torrent";
    return host.split(".")[0].replace(/^[a-z]/, (c) => c.toUpperCase());
  } catch {
    return "Mirror";
  }
}

function isProtectorOrDl(u) {
  if (/^magnet:/.test(u)) return true;
  try {
    const host = new URL(u).hostname;
    return /filecrypt|keeplinks|ddownload|rapidgator|nitroflare|katfile|uptobox|1fichier|gofile|pixeldrain|mediafire|mega\.(nz|io|co)|bayfiles|krakenfiles|send\.cm|multiup|fuckingfast|datanodes|filekeeper|buzzheavier|bzzhr|uploadhaven|alldebrid/.test(
      host
    );
  } catch {
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Detail page                                                         */
/* ------------------------------------------------------------------ */
function parseDetail(md, fallback) {
  const lines = md.split("\n");
  let title = "";
  let releaseNote = "";
  let cover = "";
  let youtube = "";
  let languages = "";
  let uploadSizeMb = "";
  let rarParts = "";
  const features = [];

  // First H2 like "## Resonance A Plague Tale Legacy (2026), 35.08GB"
  for (const line of lines) {
    const h2 = line.match(/^##\s+(.+?)\s*$/);
    if (h2 && !/^(DDOWNLOAD|RAPIDGATOR|RG|DDL|TORRENT|MEGA|MEDIAFIRE|KATFILE|UPTOBOX|NITROFLARE|1FICHIER|GOFILE|PIXELDRAIN|BAYFILES)\b/i.test(h2[1])) {
      title = h2[1].trim();
      break;
    }
  }

  // Release note: first ### that talks about the ElAmigos release / crack.
  for (const line of lines) {
    const h3 = line.match(/^###\s+(.+?)\s*$/);
    if (h3 && /ElAmigos release|already cracked|Updated to version/i.test(h3[1])) {
      releaseNote = h3[1].trim();
      break;
    }
  }

  // Images: first real cover image is the poster (fastpic/postimg/steamstatic
  // or an image hosted on elamigos.site itself).
  for (const line of lines) {
    const img = line.match(/!\[\]\((https?:\/\/[^)]+)\)/);
    if (img && /fastpic|postimg|imageban|imgur|steamstatic|elamigos\.site\/img/.test(img[1])) {
      cover = img[1];
      break;
    }
  }

  // YouTube
  for (const line of lines) {
    const yt = line.match(/(https?:\/\/(?:www\.)?youtube\.com\/watch\?v=[\w-]+|https?:\/\/youtu\.be\/[\w-]+)/);
    if (yt) {
      youtube = yt[1].replace("youtu.be/", "www.youtube.com/watch?v=");
      if (!youtube.includes("youtube.com/watch")) youtube = `https://www.youtube.com/watch?v=${youtube.split("/").pop()}`;
      break;
    }
  }

  for (const line of lines) {
    const t = line.replace(/^#{2,6}\s*/, "").trim();
    let m;
    if (!languages && (m = t.match(/^Languages?:\s*(.+)$/i))) languages = m[1].trim();
    if (!uploadSizeMb && (m = t.match(/^Upload size[^:]*:\s*([\d.,]+\s*[MGT]B)/i))) uploadSizeMb = m[1].trim();
    if (!rarParts && (m = t.match(/^RAR parts?:\s*(.+)$/i))) rarParts = m[1].trim();
  }

  // Crack credits (Codex/Rune/etc.) for features.
  const crackM = releaseNote.match(/crack by ([^)]+)\)/i);
  if (crackM) features.push(`Crack: ${crackM[1].trim()}`);
  const verM = releaseNote.match(/Updated to version\s+([0-9][0-9a-zA-Z.\-]*)/i);
  const version = verM ? verM[1].trim() : "";

  // ---- links, grouped under the most recent mirror heading ----
  // Main mirror sections come before any update/extra block; links found in
  // later blocks are labelled as update/extra downloads.
  const links = [];
  const seenUrl = new Set();
  let section = "";
  let blockLabel = "";
  for (const line of lines) {
    const h2 = line.match(/^##\s+(.+?)\s*$/);
    if (h2) {
      const raw = h2[1].trim();
      const name = raw.toUpperCase().replace(/[^A-Z0-9]/g, "");
      const isMirror =
        MIRROR_HOSTS[name] ||
        /^(DDOWNLOAD|RAPIDGATOR|RG|DDL|TORRENT|MEGA|MEDIAFIRE|KATFILE|UPTOBOX|NITROFLARE|1FICHIER|GOFILE|PIXELDRAIN|BAYFILES)/.test(name);
      if (isMirror) {
        section = raw;
        continue;
      }
      // Game title H2 (first heading, contains the size) resets everything;
      // any other H2 marks an update/extra block whose mirror sections follow.
      const isTitleHeading = /\(\d{4}/.test(raw) && /[MGT]B\s*$/i.test(raw);
      if (isTitleHeading) {
        section = "";
        blockLabel = "";
      } else {
        section = "";
        blockLabel = /update|crackfix|patch/i.test(raw)
          ? "Update"
          : /textures?|dlc|pack|bonus|soundtrack/i.test(raw)
            ? "Extra"
            : blockLabel; // keep the current block label inside update notes
      }
      continue;
    }
    // collect links in this line. ElAmigos pages render each link as
    // [https://host/...](https://host/...) — text and href identical — so
    // strip markdown link constructs first, then read their href, then any
    // leftover bare URLs.
    const urls = [];
    let stripped = line.replace(/\[[^\]]*\]\((https?:\/\/[^)\s]+)\)/g, (_m, href) => {
      urls.push(href);
      return " ";
    });
    for (const raw of stripped.match(/https?:\/\/[^\s)\]]+/g) || []) {
      if (!urls.includes(raw)) urls.push(raw);
    }
    if (!section) continue;
    for (const u of urls) {
      if (!isProtectorOrDl(u)) continue;
      if (u.includes("youtube.com")) continue;
      if (seenUrl.has(u)) continue;
      seenUrl.add(u);
      const secKey = section.toUpperCase().replace(/[^A-Z0-9]/g, "");
      const mirrorName = MIRROR_HOSTS[secKey] || MIRROR_HOSTS[secKey.replace(/\d+$/, "")] || section;
      const isTorrent = /TORRENT/i.test(section) || /^magnet:/.test(u);
      const prefix = blockLabel ? `${blockLabel}: ` : "";
      links.push({
        name: isTorrent
          ? `${prefix}${mirrorName} (Torrent)`
          : `${prefix}${mirrorName} – ${linkHostLabel(u)}`,
        url: u,
        type: isTorrent ? "torrent" : "repack",
      });
    }
  }

  // Title cleanup: strip trailing ", 35.08GB" and year parens for the clean name,
  // keep a display title with year.
  let cleanName = title
    .replace(/,\s*[\d.,]+\s*[MGT]B\s*$/i, "")
    .replace(/\s*\((\d{4}(?:\s*\/\s*\d{4})?)\)\s*$/, "")
    .trim();
  const yearM = title.match(/\((\d{4})/);
  const year = yearM ? yearM[1] : "";
  if (year && !features.includes(`Year: ${year}`)) features.push(`Year: ${year}`);
  if (languages) {
    const n = languages.split(",").length;
    if (n > 1) features.push(`Languages: MULTi${n}`);
    else features.push(`Language: ${languages.trim()}`);
  }
  if (fallback?.hasHypervisor) features.push("Hypervisor build");

  const description =
    releaseNote ||
    `${fallback?.title || cleanName} — ElAmigos repack${version ? ` (v${version})` : ""}${uploadSizeMb ? `, download size ${uploadSizeMb}` : ""}. Game is pre-installed/cracked after extraction.`;

  const ytThumb = youtube
    ? `https://i.ytimg.com/vi/${(youtube.match(/v=([\w-]+)/) || [])[1] || ""}/hqdefault.jpg`
    : "";

  return {
    title: fallback?.title && fallback.title.length >= cleanName.length ? fallback.title : cleanName || fallback?.title || "",
    rawTitle: title || fallback?.rawTitle || "",
    href: fallback?.slug || "",
    date: fallback?.date || "",
    detailUrl: fallback?.url || "",
    version,
    size: uploadSizeMb || "",
    rarParts: rarParts || "",
    languages,
    description,
    img: cover || "",
    poster: cover || "",
    icon: cover || "",
    banner: ytThumb,
    videoUrl: youtube || "",
    videoThumbnail: ytThumb || "",
    screenshots: [cover, ytThumb].filter(Boolean),
    features,
    category: "pc-games",
    subcategory: "",
    platform: "windows",
    downloads: links.length,
    downloadLinks: links,
    // mirror the links in `downloads` too, so every importer branch sees them
    downloads_links: links,
    hasLinks: links.length > 0,
    hasHypervisor: !!fallback?.hasHypervisor,
    updates: fallback?.updates || [],
    source: "elamigos",
    createdAt: new Date().toISOString().split("T")[0],
  };
}

/* ------------------------------------------------------------------ */
/* Fetch helpers (live mode)                                           */
/* ------------------------------------------------------------------ */
async function fetchText(url) {
  const c = new AbortController();
  const t = setTimeout(() => c.abort(), DETAIL_TIMEOUT_MS);
  try {
    const r = await fetch(url, {
      headers: { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36" },
      signal: c.signal,
      redirect: "follow",
    });
    if (!r.ok) return { ok: false, text: "", status: r.status };
    return { ok: true, text: await r.text(), status: r.status };
  } catch (e) {
    return { ok: false, text: "", status: 0, error: String(e?.message || e) };
  } finally {
    clearTimeout(t);
  }
}

async function main() {
  mkdirSync(dirname(OUT_FULL), { recursive: true });

  let indexMd;
  let detailSource = "live";

  if (RAW_DIR) {
    const idxPath = join(RAW_DIR, "index.md");
    if (!existsSync(idxPath)) {
      console.error(`Offline mode: ${idxPath} not found`);
      process.exit(1);
    }
    indexMd = readFileSync(idxPath, "utf8");
    detailSource = "raw";
    console.log(`Offline mode: reading pages from ${RAW_DIR}`);
  } else {
    console.log(`Fetching index ${INDEX_URL} ...`);
    const res = await fetchText(INDEX_URL);
    if (!res.ok) {
      console.error(`Index fetch failed (status ${res.status}): ${res.error || ""}`);
      process.exit(1);
    }
    indexMd = toCanonical(res.text);
  }

  let entries = parseIndex(toCanonical(indexMd));
  if (LIMIT > 0) entries = entries.slice(0, LIMIT);
  console.log(`Parsed ${entries.length} index entries${LIMIT ? ` (limited to ${LIMIT})` : ""}`);

  const games = [];
  let done = 0;
  let withLinks = 0;

  async function processEntry(entry) {
    let md = "";
    if (detailSource === "raw") {
      const rawPath = join(RAW_DIR, entry.slug.replace(/\.html$/, "") + ".md");
      if (existsSync(rawPath)) md = readFileSync(rawPath, "utf8");
    } else {
      const res = await fetchText(entry.url);
      if (res.ok) md = toCanonical(res.text);
      else console.warn(`  ! ${entry.slug} -> ${res.status} ${res.error || ""}`);
    }
    if (md) {
      const g = parseDetail(md, entry);
      games.push(g);
      if (g.downloadLinks.length > 0) withLinks++;
    } else {
      games.push({ ...entry, title: entry.title, downloadLinks: [], downloads: 0, hasLinks: false, source: "elamigos" });
    }
    done++;
    if (done % 10 === 0 || done === entries.length) {
      process.stdout.write(`\r  detail pages: ${done}/${entries.length} (with links: ${withLinks})   `);
    }
  }

  for (let i = 0; i < entries.length; i += CONC) {
    const batch = entries.slice(i, i + CONC);
    await Promise.all(batch.map(processEntry));
    if (detailSource === "live") await sleep(120);
  }
  console.log("");

  // Preserve index order (newest first).
  const bySlug = new Map(games.map((g) => [g.href || g.slug || g.detailUrl, g]));
  const ordered = entries.map((e) => bySlug.get(e.slug)).filter(Boolean);

  writeFileSync(OUT_FULL, JSON.stringify(ordered, null, 2));
  console.log(`Saved ${ordered.length} games to ${OUT_FULL}`);
  console.log(`Games with download links: ${withLinks}/${ordered.length}`);
}

main().catch((e) => {
  console.error("Fatal:", e);
  process.exit(1);
});
